  mensajes: cons.mensajes
} }];

const ctx = $('Preparar contexto').first().json || {};
const c = $('Contrato de datos').first().json || {};
function field(s,key){ const parts=String(s||'').split('|'); for (const p of parts){ const t=p.trim(); if (t.toLowerCase().indexOf(key.toLowerCase()+':')===0) return t.slice(key.length+1).trim(); } return ''; }
const prev = ctx.datos_clave || '';
const nombre=(c.nombre||'').trim(), motivo=(c.motivo||'').trim(), turno=((c.fecha||'')+' '+(c.hora||'')).trim();
const paciente = nombre || field(prev,'Paciente');
const mot = motivo || field(prev,'Motivo');
const tur = turno || field(prev,'Turno');
const datos_clave = 'Paciente: ' + paciente + ' | Motivo: ' + mot + ' | Turno: ' + tur;
return [{ json: { session_id: ctx.session_id, mensajes: ctx.mensajes, last_summary: ctx.last_summary, datos_clave: datos_clave, estado: ctx.estado || 'En Progreso' } }];

const j=$input.first().json||{};
// Webhook (petición asincrónica): llega ya validado por "Entrada webhook"
if (j.canal === 'webhook') {
  return [{ json: { sessionId: j.sessionId, mensaje: j.mensaje, email_entrada: j.email || '', nombre_remitente: j.nombre || '', canal: 'webhook', tg_chat_id: j.tg_chat_id || '', request_id: j.request_id, traceId: j.traceId, trace_inicio: j.trace_inicio } }];
}
// Telegram (voz o texto): llega ya preparado por "Entrada Telegram"
if (String(j.canal||'').startsWith('telegram')) {
  return [{ json: { sessionId: j.sessionId, mensaje: j.mensaje, email_entrada: '', nombre_remitente: j.nombre_remitente||'', canal: j.canal, tg_chat_id: j.tg_chat_id, tg_username: j.tg_username || '', update_id: j.update_id } }];
}
const isEmail=(j.From!==undefined)||(j.BodyText!==undefined);
const rawFrom=String(j.From||"");
const m=rawFrom.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
const email=m?m[0]:"";
let disp = rawFrom.includes("<") ? rawFrom.split("<")[0] : "";
disp = disp.replace(/["']/g,"").trim();
if(disp.includes("@")) disp="";
const sessionId=isEmail ? (email||rawFrom.replace(/["']/g,"")) : String(j.sessionId||"");
const mensaje=j.chatInput||j.BodyText||j.Subject||"";
const email_entrada=isEmail?email:"";
const nombre_remitente=isEmail?disp:"";
const canal=isEmail?"email":"chat";
return [{ json: { sessionId, mensaje, email_entrada, nombre_remitente, canal } }];

function grab(node,path){ try{ let o=$(node).first().json; for(const k of path.split('.')){ o=o[k]; } return o||''; }catch(e){ return ''; } }
let m = grab('Caso rojo','respuesta_fija')
     || grab('Aplicar validación','output')
     || grab('Confirmacion (Worker 2)','data.mensaje')
     || grab('Aviso (no se puede)','data.mensaje')
     || grab('Consultar turno (Worker 3)','data.mensaje')
     || grab('Consultar turno (Worker 3)','mensaje');
// Sin respuesta de ninguna rama: FUERA_DE_ALCANCE (sale por el Fallback del Switch) o un caso no previsto.
// Antes caía en un "Listo." genérico.
if (!m) {
  const intent = grab('Contrato de datos','intent');
