    ? 'Solo puedo ayudarte con turnos e información de la Clínica LoDeTincho. Esa consulta no la puedo responder.'
    : 'No pude procesar tu pedido. ¿Me lo repetís con otras palabras?';
}
return [{ json: { output: m } }];

