// Caso que se envía al Juez: pregunta, respuesta, fragmentos RAG recuperados en ESTE intento y memoria de Airtable.
const steps = $json.intermediateSteps || [];
const frags = steps
  .filter(s => s.action && String(s.action.tool || '').startsWith('consultar_conocimiento'))
  .map(s => typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation));
const mem = $('Preparar contexto').first().json || {};
return [{ json: {
  traceId: $('Generar traceId').first().json.traceId,
  parentExecutionId: $execution.id,
  origen: 'manager',
  arquitectura: 'A (producción)',
  intento: $runIndex + 1,
  execution_id: $execution.id,
  pregunta: $('Normalizar entrada').first().json.mensaje,
  respuesta: $json.output || '',
  fragmentos: frags.length ? frags.join('\n\n=====\n\n') : '(el asistente no consultó la base documental)',
  busquedas: frags.length,
  contexto_airtable: { estado: mem.estado || '', resumen: mem.last_summary || '', datos_clave: mem.datos_clave || '' }
} }];

// Respuesta final de la ruta INFO (aceptada por el Juez, aprobada o editada por un humano).
// Si hubo escalado, siempre se informa la derivación a un operador, apruebe o edite la persona.
const DERIVACION = 'Un operador de la clínica ya fue avisado y se va a comunicar con vos.';
let out = $json.respuesta_final || '';
if (String($json.ruta_final || '').startsWith('ESCALADO')) out = out.trim() + '\n\n' + DERIVACION;
return [{ json: {
  output: out,
  validacion: $json.ruta_final || '',
  exactitud_factual: $json.exactitud_factual ?? null,
  critica: $json.critica || ''
} }];

// Respuesta para el canal de voz: sin citas, links, emojis ni markdown, y como máximo 200 caracteres
// (ElevenLabs cobra por carácter; la regla también está en el System Prompt del Agente RAG).
const MAX = 200;
const original = String($json.output || '');
let t = original
  .replace(/\[Fuente:[^\]]*\]/gi, '')          // citas de fuente (quedan en el texto, no en el audio)
  .replace(/https?:\/\/\S+/g, '')              // URLs
  .replace(/[*_`#>]/g, '')                     // markdown
  .replace(/^\s*[-•]\s+/gm, '')                // viñetas
  .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '') // emojis
  .split(/\s*\n+\s*/).map(s => s.trim()).filter(Boolean)
  // cada línea se une como frase: si no termina en signo, se le agrega un punto ("atienden:" -> "atienden:")
  .map(s => /[.?!:;,]$/.test(s) ? s : s + '.').join(' ')
  .replace(/\s{2,}/g, ' ').trim();
if (t.length > MAX) {
  // cortar en el último fin de oración (. ? !) que entre en 200; si no hay, en la última palabra
  const corte = t.slice(0, MAX + 1);
  // fines de oración reales: no cuentan las abreviaturas (Dr., Dra., Sr., Sra., Lic., etc.)
  let fin = -1;
  for (const m of corte.matchAll(/[.?!](?=\s|$)/g)) {
    const previa = corte.slice(0, m.index).split(/\s/).pop();
    if (m[0] === '.' && /^(Dr|Dra|Sr|Sra|Lic|Dres|Av|Nro|Ing)$/i.test(previa)) continue;
    fin = m.index;
  }
  t = (fin > 60 ? corte.slice(0, fin + 1) : corte.slice(0, corte.lastIndexOf(' ')) + '…').trim();
}
const n = $('Normalizar entrada').first().json;
return [{ json: { texto_voz: t, caracteres: t.length, texto_completo: original, canal: n.canal, tg_chat_id: n.tg_chat_id } }];

